"""Exception hierarchy for microdb."""

from __future__ import annotations


class MicroDBError(Exception):
    """Base class for every error raised by microdb."""


class LexError(MicroDBError):
    """Invalid character or malformed literal in the query text."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(f"{message} at offset {offset}")
        self.offset = offset


class ParseError(MicroDBError):
    """Query text that does not match the grammar."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(f"{message} at offset {offset}")
        self.offset = offset


class SchemaError(MicroDBError):
    """Invalid table definition or cell value."""


class TypeMismatchError(MicroDBError):
    """Operands or arguments of an incompatible type."""


class UnknownColumnError(MicroDBError):
    """Reference to a column that does not exist."""


class AmbiguousColumnError(MicroDBError):
    """Unqualified column name that matches more than one column."""


class UnknownTableError(MicroDBError):
    """Reference to a table that is not available."""


class UnknownFunctionError(MicroDBError):
    """Call to a function that does not exist."""


class ArityError(MicroDBError):
    """Function called with the wrong number of arguments."""


class AggregateError(MicroDBError):
    """Aggregate used where it is not allowed."""


class GroupingError(MicroDBError):
    """Select item that is neither grouped nor aggregated."""

"""Value model: type names, three-valued logic, comparison and arithmetic.

A logical value is True, False or UNKNOWN, where UNKNOWN is represented by None.
"""

from __future__ import annotations

from .errors import TypeMismatchError

_ARITH_OPS = ("+", "-", "*", "/", "%")


def type_of(v: object) -> str:
    """Return the microdb type name of a value."""
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"unsupported value {v!r}")


def is_numeric(v: object) -> bool:
    """True for INT and FLOAT values; False for BOOL and NULL."""
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def and_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued AND."""
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued OR."""
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    """Three-valued NOT; NOT UNKNOWN is UNKNOWN."""
    if a is None:
        return None
    return not a


def _comparison_kind(a: object, b: object) -> str:
    """Validate that two non-NULL values are comparable and name their kind."""
    ta, tb = type_of(a), type_of(b)
    if ta in ("INT", "FLOAT") and tb in ("INT", "FLOAT"):
        return "NUMERIC"
    if ta == tb:
        return ta
    raise TypeMismatchError(f"cannot compare {ta} with {tb}")


def compare_eq(a: object, b: object) -> bool | None:
    """SQL equality: UNKNOWN when either side is NULL."""
    if a is None or b is None:
        return None
    _comparison_kind(a, b)
    return a == b


def compare_lt(a: object, b: object) -> bool | None:
    """SQL less-than: UNKNOWN when either side is NULL."""
    if a is None or b is None:
        return None
    _comparison_kind(a, b)
    return a < b


def group_key(values: tuple[object, ...] | list[object]) -> tuple[object, ...]:
    """Hashable key where NULL equals NULL and INT/FLOAT compare numerically."""
    return tuple(_key_part(v) for v in values)


def _key_part(v: object) -> tuple[str, object]:
    if v is None:
        return ("NULL", None)
    kind = type_of(v)
    if kind in ("INT", "FLOAT"):
        return ("NUMERIC", v)
    return (kind, v)


def _require_numeric(op: str, a: object, b: object) -> None:
    if not (is_numeric(a) and is_numeric(b)):
        raise TypeMismatchError(
            f"operator {op} requires numeric operands, got {type_of(a)} and {type_of(b)}"
        )


def arith(op: str, a: object, b: object) -> object:
    """Arithmetic on INT/FLOAT; NULL propagates; division or modulo by zero gives NULL."""
    if op not in _ARITH_OPS:
        raise ValueError(f"unknown arithmetic operator {op!r}")
    if a is None or b is None:
        return None
    _require_numeric(op, a, b)
    if op == "/":
        # Division always yields FLOAT, Python's true division does exactly that.
        return None if b == 0 else a / b
    if op == "%":
        if type_of(a) != "INT" or type_of(b) != "INT":
            raise TypeMismatchError("operator % requires INT operands")
        return None if b == 0 else a % b
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    return a * b


def negate(a: object) -> object:
    """Unary minus; preserves the numeric type and propagates NULL."""
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"unary minus requires a numeric operand, got {type_of(a)}")
    return -a

"""Schema layer: column definitions and validated in-memory tables."""

from __future__ import annotations

import dataclasses

from .errors import SchemaError

TYPE_NAMES = ("INT", "FLOAT", "TEXT", "BOOL")


@dataclasses.dataclass(frozen=True)
class Column:
    """A named, typed column."""

    name: str
    type: str


def _is_int(v: object) -> bool:
    return isinstance(v, int) and not isinstance(v, bool)


def coerce_cell(value: object, type_name: str) -> object:
    """Validate one cell against its column type, widening INT to FLOAT."""
    if value is None:
        return None
    if type_name == "FLOAT" and _is_int(value):
        return float(value)
    checks = {
        "INT": _is_int,
        "FLOAT": lambda v: isinstance(v, float),
        "TEXT": lambda v: isinstance(v, str),
        "BOOL": lambda v: isinstance(v, bool),
    }
    if type_name not in checks or not checks[type_name](value):
        raise SchemaError(f"value {value!r} does not match column type {type_name}")
    return value


class Table:
    """A named table with validated columns and rows."""

    def __init__(self, name: str, columns: list[Column], rows: list[list[object]]) -> None:
        self._name = name
        self._columns = list(columns)
        self._validate_columns()
        self._rows = [self._check_row(row) for row in rows]

    def _validate_columns(self) -> None:
        if not self._columns:
            raise SchemaError(f"table {self._name!r} must have at least one column")
        seen: set[str] = set()
        for column in self._columns:
            if column.type not in TYPE_NAMES:
                raise SchemaError(f"unknown column type {column.type!r} for {column.name!r}")
            if column.name in seen:
                raise SchemaError(f"duplicate column name {column.name!r}")
            seen.add(column.name)

    def _check_row(self, row: list[object]) -> list[object]:
        if len(row) != len(self._columns):
            raise SchemaError(
                f"row has {len(row)} values but table {self._name!r} has {len(self._columns)} columns"
            )
        return [coerce_cell(v, c.type) for v, c in zip(row, self._columns)]

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return list(self._columns)

    @property
    def rows(self) -> list[list[object]]:
        return self._rows

    def column_index(self, name: str) -> int:
        """Position of a column; raises SchemaError when the name is unknown."""
        for index, column in enumerate(self._columns):
            if column.name == name:
                return index
        raise SchemaError(f"table {self._name!r} has no column {name!r}")

