class MicroDBError(Exception):
    """Base class for every error raised by microdb."""


class LexError(MicroDBError):
    """A character sequence that cannot be tokenized. ``offset`` is zero-based."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class ParseError(MicroDBError):
    """A token sequence that does not match the grammar. ``offset`` is zero-based."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class SchemaError(MicroDBError):
    """An invalid table definition or cell value."""


class TypeMismatchError(MicroDBError):
    """An operation applied to a value of an unsupported type."""


class UnknownColumnError(MicroDBError):
    """A column reference that matches no input column."""


class AmbiguousColumnError(MicroDBError):
    """An unqualified column name that matches more than one input column."""


class UnknownTableError(MicroDBError):
    """A table name that is not supplied or not part of the query."""


class UnknownFunctionError(MicroDBError):
    """A function name that is neither scalar nor aggregate."""


class ArityError(MicroDBError):
    """A function called with the wrong number of arguments."""


class AggregateError(MicroDBError):
    """An aggregate used where it is not allowed."""


class GroupingError(MicroDBError):
    """A select item that is neither aggregated nor a grouping expression."""

"""Value model: kinds, three-valued logic, comparison and arithmetic.

NULL is represented by ``None``. Logical values are ``True``, ``False`` and
UNKNOWN, which is also ``None``.
"""

from __future__ import annotations

from .errors import TypeMismatchError

TYPE_NAMES: tuple[str, ...] = ("INT", "FLOAT", "TEXT", "BOOL")


def _kind_or_none(v: object) -> str | None:
    """Return the type name of a non-NULL value, or None if unsupported."""
    for cls, name in ((bool, "BOOL"), (int, "INT"), (float, "FLOAT"), (str, "TEXT")):
        if isinstance(v, cls):
            return name
    return None


def type_of(v: object) -> str:
    """Return the value kind: INT, FLOAT, TEXT, BOOL or NULL."""
    if v is None:
        return "NULL"
    kind = _kind_or_none(v)
    if kind is None:
        raise TypeMismatchError(f"unsupported value {v!r}")
    return kind


def is_numeric(v: object) -> bool:
    """True for int and float; False for bool and NULL."""
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _check_logical(*values: object) -> None:
    for v in values:
        if v is not None and not isinstance(v, bool):
            raise TypeMismatchError(f"expected a logical value, got {type_of(v)}")


def and_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued AND: FALSE dominates, then UNKNOWN, then TRUE."""
    _check_logical(a, b)
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued OR: TRUE dominates, then UNKNOWN, then FALSE."""
    _check_logical(a, b)
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    """Three-valued NOT: NOT UNKNOWN is UNKNOWN."""
    _check_logical(a)
    return None if a is None else not a


def _family(v: object) -> str:
    kind = type_of(v)
    return "NUM" if kind in ("INT", "FLOAT") else kind


def _check_comparable(a: object, b: object) -> None:
    if a is None or b is None:
        raise TypeMismatchError("NULL has no ordering")
    if _family(a) != _family(b):
        raise TypeMismatchError(f"cannot compare {type_of(a)} with {type_of(b)}")


def compare_eq(a: object, b: object) -> bool | None:
    """SQL equality: UNKNOWN if either side is NULL."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a == b


def compare_lt(a: object, b: object) -> bool | None:
    """SQL less-than: UNKNOWN if either side is NULL."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a < b


def compare_values(a: object, b: object) -> int:
    """Total order over non-NULL values of one family: returns -1, 0 or 1."""
    _check_comparable(a, b)
    return (a > b) - (a < b)  # type: ignore[operator]


def _check_numeric(*values: object) -> None:
    for v in values:
        if not is_numeric(v):
            raise TypeMismatchError(f"expected a numeric value, got {type_of(v)}")


def _modulo(a: object, b: object) -> object:
    if type_of(a) != "INT" or type_of(b) != "INT":
        raise TypeMismatchError("% requires INT operands")
    return None if b == 0 else a % b  # type: ignore[operator]


def arith(op: str, a: object, b: object) -> object:
    """Arithmetic with NULL propagation. ``/`` always yields FLOAT.

    Division or modulo by zero yields NULL.
    """
    if a is None or b is None:
        return None
    _check_numeric(a, b)
    if op == "/":
        return None if b == 0 else float(a) / float(b)  # type: ignore[arg-type]
    if op == "%":
        return _modulo(a, b)
    if op == "+":
        return a + b  # type: ignore[operator]
    if op == "-":
        return a - b  # type: ignore[operator]
    if op == "*":
        return a * b  # type: ignore[operator]
    raise ValueError(f"unknown arithmetic operator {op!r}")


def negate(a: object) -> object:
    """Unary minus; preserves the numeric type. NULL stays NULL."""
    if a is None:
        return None
    _check_numeric(a)
    return -a  # type: ignore[operator]

