        self.offset = offset


class SchemaError(MicroDBError):
    """Invalid table definition or cell value."""


class TypeMismatchError(MicroDBError):
    """Operands or arguments have an incompatible type."""


class UnknownColumnError(MicroDBError):
    """Column reference does not resolve."""


class AmbiguousColumnError(MicroDBError):
    """Unqualified column name exists in more than one table."""


class UnknownTableError(MicroDBError):
    """Table name is not supplied or not in scope."""


class UnknownFunctionError(MicroDBError):
    """Function name is not known."""


class ArityError(MicroDBError):
    """Function called with the wrong number of arguments."""


class AggregateError(MicroDBError):
    """Aggregate used where it is not allowed."""


class GroupingError(MicroDBError):
    """Select item is neither grouped nor aggregated."""

"""Value model: type names, three-valued logic, comparison and arithmetic."""

from .errors import TypeMismatchError


def type_of(v: object) -> str:
    """Return the microdb type name of a value."""
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"unsupported value {v!r}")


def is_numeric(v: object) -> bool:
    """True for INT and FLOAT values; bool is excluded."""
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def as_logical(v: object) -> bool | None:
    """Accept a logical value (bool or UNKNOWN); reject anything else."""
    if v is None or isinstance(v, bool):
        return v
    raise TypeMismatchError(f"expected a logical value, got {type_of(v)}")


def and_(a: bool | None, b: bool | None) -> bool | None:
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    return None if a is None else not a


def _kind(v: object) -> str:
    return "NUM" if is_numeric(v) else type_of(v)


def _check_comparable(a: object, b: object) -> None:
    if _kind(a) != _kind(b):
        raise TypeMismatchError(f"cannot compare {type_of(a)} with {type_of(b)}")


def compare_eq(a: object, b: object) -> bool | None:
    """SQL equality: UNKNOWN (None) if either side is NULL."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a == b


def compare_lt(a: object, b: object) -> bool | None:
    """SQL less-than: UNKNOWN (None) if either side is NULL."""
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a < b


def compare(op: str, a: object, b: object) -> bool | None:
    """Evaluate one of the six comparison operators with NULL propagation."""
    if op == "=":
        return compare_eq(a, b)
    if op == "<>":
        return not_(compare_eq(a, b))
    if op == "<":
        return compare_lt(a, b)
    if op == ">":
        return compare_lt(b, a)
    if op == "<=":
        return or_(compare_lt(a, b), compare_eq(a, b))
    if op == ">=":
        return or_(compare_lt(b, a), compare_eq(a, b))
    raise ValueError(f"unknown comparison {op}")


def arith(op: str, a: object, b: object) -> object:
    """Arithmetic with NULL propagation; division or modulo by zero gives NULL."""
    if a is None or b is None:
        return None
    if not (is_numeric(a) and is_numeric(b)):
        raise TypeMismatchError(f"operator {op} requires numeric operands")
    if op == "%":
        if type_of(a) != "INT" or type_of(b) != "INT":
            raise TypeMismatchError("operator % requires INT operands")
        return None if b == 0 else a % b
    if op == "/":
        return None if b == 0 else a / b
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    raise ValueError(f"unknown operator {op}")


def negate(a: object) -> object:
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"cannot negate {type_of(a)}")
    return -a


def group_key(v: object) -> tuple:
    """Hashable grouping/DISTINCT key in which NULL equals NULL.

    Booleans are kept apart from numbers so that True does not merge with 1.
    """
    if v is None:
        return ("NULL",)
    if isinstance(v, bool):
        return ("BOOL", v)
    if isinstance(v, (int, float)):
        return ("NUM", v)
    return ("TEXT", v)

"""Schema layer: columns and validated in-memory tables."""

from __future__ import annotations

import dataclasses

from .errors import SchemaError

TYPE_NAMES = ("INT", "FLOAT", "TEXT", "BOOL")


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str  # one of TYPE_NAMES


def _coerce(col: Column, v: object) -> object:
    """Validate one cell against its column type, widening int to float."""
    if v is None:
        return None
    if col.type == "BOOL" and isinstance(v, bool):
        return v
    if col.type == "TEXT" and isinstance(v, str):
        return v
    if col.type == "INT" and type(v) is int:
        return v
    if col.type == "FLOAT":
        if type(v) is float:
            return v
        if type(v) is int:
            return float(v)
    raise SchemaError(f"value {v!r} does not match column {col.name!r} of type {col.type}")


class Table:
    """A named table whose rows are validated against its columns."""

    def __init__(self, name: str, columns: list[Column], rows: list[list[object]]) -> None:
        if not columns:
            raise SchemaError("a table must have at least one column")
        seen: set[str] = set()
        for col in columns:
            if col.name in seen:
                raise SchemaError(f"duplicate column name {col.name!r}")
            if col.type not in TYPE_NAMES:
                raise SchemaError(f"unknown column type {col.type!r}")
            seen.add(col.name)
        self._name = name
        self._columns = list(columns)
        self._rows = [self._check_row(row) for row in rows]

    def _check_row(self, row: list[object]) -> list[object]:
        values = list(row)
        if len(values) != len(self._columns):
            raise SchemaError(
                f"row has {len(values)} cells but table {self._name!r} has {len(self._columns)} columns"
            )
        return [_coerce(col, v) for col, v in zip(self._columns, values)]

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return list(self._columns)

    @property
    def rows(self) -> list[list[object]]:
        return self._rows

    def column_index(self, name: str) -> int:
        for i, col in enumerate(self._columns):
            if col.name == name:
                return i
        raise SchemaError(f"table {self._name!r} has no column {name!r}")

"""Hand-written lexer: turns query text into a list of tokens."""

from __future__ import annotations

import re
from dataclasses import dataclass

from .errors import LexError

KEYWORDS = frozenset({
    "SELECT", "DISTINCT", "FROM", "INNER", "LEFT", "JOIN", "ON", "WHERE",
    "GROUP", "BY", "HAVING", "ORDER", "ASC", "DESC", "LIMIT", "OFFSET",
    "AS", "AND", "OR", "NOT", "IS", "NULL", "TRUE", "FALSE",
})

_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
# digits.digits | digits. | .digits | digits, each with an optional exponent
_NUMBER = re.compile(r"(?:[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)(?:[eE][+-]?[0-9]+)?")
_TWO_CHAR_OPS = ("<>", "<=", ">=")
_ONE_CHAR_OPS = frozenset("=<>+-*/%(),.")


@dataclass(frozen=True)
class Token:
    """kind is INT, FLOAT, TEXT, IDENT, KW, OP or EOF; offsets are zero-based."""

    kind: str
    value: object
    offset: int
    end: int


def tokenize(source: str) -> list[Token]:
    """Split source into tokens, always ending with an EOF token."""
    tokens: list[Token] = []
    pos = 0
    while True:
        pos = _skip_blank(source, pos)
        if pos >= len(source):
            tokens.append(Token("EOF", None, pos, pos))
            return tokens
        tok = _lex_one(source, pos)
        tokens.append(tok)
        pos = tok.end


def _skip_blank(source: str, pos: int) -> int:
    """Skip whitespace and ``--`` line comments."""
    n = len(source)
    while pos < n:
        if source[pos].isspace():
            pos += 1
        elif source.startswith("--", pos):
            newline = source.find("\n", pos)
            pos = n if newline < 0 else newline + 1
        else:
            break
    return pos


def _lex_one(source: str, pos: int) -> Token:
    ch = source[pos]
    if ch == "'":
        return _lex_text(source, pos)
    match = _NUMBER.match(source, pos)
    if match:
        return _number_token(match.group(), pos, match.end())
    match = _IDENT.match(source, pos)
    if match:
        word = match.group()
        upper = word.upper()
        kind, value = ("KW", upper) if upper in KEYWORDS else ("IDENT", word)
        return Token(kind, value, pos, match.end())
    two = source[pos:pos + 2]
    if two in _TWO_CHAR_OPS:
        return Token("OP", two, pos, pos + 2)
    if ch in _ONE_CHAR_OPS:
        return Token("OP", ch, pos, pos + 1)
    raise LexError(f"unexpected character {ch!r} at offset {pos}", pos)


def _number_token(text: str, pos: int, end: int) -> Token:
    if "." in text or "e" in text.lower():
        return Token("FLOAT", float(text), pos, end)
    return Token("INT", int(text), pos, end)


def _lex_text(source: str, pos: int) -> Token:
    """Lex a single-quoted literal in which '' stands for one quote."""
    chars: list[str] = []
    i = pos + 1
    n = len(source)
    while i < n:
        if source[i] == "'":
            if i + 1 < n and source[i + 1] == "'":
                chars.append("'")
                i += 2
                continue
            return Token("TEXT", "".join(chars), pos, i + 1)
        chars.append(source[i])
        i += 1
    raise LexError(f"unterminated text literal at offset {pos}", pos)

"""Recursive-descent parser: token list -> Query AST."""

from __future__ import annotations

from dataclasses import dataclass

from .aggregate import AGGREGATE_NAMES
from .errors import ParseError
from .lexer import Token, tokenize

CMP_OPS = frozenset({"=", "<>", "<", "<=", ">", ">="})


@dataclass(frozen=True)
class Lit:
    value: object
    tag: str  # INT, FLOAT, TEXT, BOOL or NULL; keeps Lit(1) apart from Lit(True)


@dataclass(frozen=True)
class Col:
    qualifier: str | None
    name: str


@dataclass(frozen=True)
class Unary:
    op: str  # "-" or "not"
    operand: "Expr"


@dataclass(frozen=True)
class Binary:
    op: str  # "and", "or", comparison operators, or arithmetic operators
    left: "Expr"
    right: "Expr"


@dataclass(frozen=True)
class IsNull:
    operand: "Expr"
    negated: bool


@dataclass(frozen=True)
class Call:
    name: str  # lower-cased
    args: tuple
    star: bool = False  # True only for count(*)


Expr = Lit | Col | Unary | Binary | IsNull | Call


@dataclass(frozen=True)
class SelectItem:
    expr: Expr
    alias: str | None
    text: str  # source text with whitespace collapsed


@dataclass(frozen=True)
class Star:
    table: str | None


@dataclass(frozen=True)
class Join:
    kind: str  # "INNER" or "LEFT"
    table: str
    on: Expr


@dataclass(frozen=True)
class OrderItem:
    expr: Expr
    desc: bool


@dataclass(frozen=True)
class Query:
    distinct: bool
    items: tuple
    table: str
    join: Join | None
    where: Expr | None
    group: tuple
    having: Expr | None
    order: tuple
    limit: int | None
    offset: int | None


def parse(source: str) -> Query:
    """Parse a query string into a Query; raises LexError or ParseError."""
    return _Parser(source).parse_query()


class _Parser:
    def __init__(self, source: str) -> None:
        self.src = source
        self.toks: list[Token] = tokenize(source)
        self.i = 0
        self.agg_depth = 0
        self.last_end = 0

    # token helpers
    def peek(self, ahead: int = 0) -> Token:
        return self.toks[min(self.i + ahead, len(self.toks) - 1)]

    def advance(self) -> Token:
        tok = self.toks[self.i]
        if tok.kind != "EOF":
            self.i += 1
        self.last_end = tok.end
        return tok

    def is_kw(self, word: str, ahead: int = 0) -> bool:
        tok = self.peek(ahead)
        return tok.kind == "KW" and tok.value == word

    def is_op(self, op: str, ahead: int = 0) -> bool:
        tok = self.peek(ahead)
        return tok.kind == "OP" and tok.value == op

    def accept_kw(self, word: str) -> bool:
        if self.is_kw(word):
            self.advance()
            return True
        return False

    def accept_op(self, op: str) -> bool:
        if self.is_op(op):
            self.advance()
            return True
        return False

    def expect_kw(self, word: str) -> None:
        if not self.accept_kw(word):
            raise self.error(f"expected {word}")

    def expect_op(self, op: str) -> None:
        if not self.accept_op(op):
            raise self.error(f"expected '{op}'")

    def expect_ident(self) -> str:
        tok = self.peek()
        if tok.kind != "IDENT":
            raise self.error("expected an identifier")
        self.advance()
        return str(tok.value)

    def error(self, message: str) -> ParseError:
        tok = self.peek()
        return ParseError(f"{message} at offset {tok.offset}", tok.offset)

    # clauses
    def parse_query(self) -> Query:
        self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT")
        items = self.parse_select_list()
        self.expect_kw("FROM")
        table = self.expect_ident()
        join = self.parse_join()
        where = self.parse_expr() if self.accept_kw("WHERE") else None
        group: tuple = ()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group = self.parse_expr_list()
        having = self.parse_expr() if self.accept_kw("HAVING") else None
        order: tuple = ()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order = self.parse_order_list()
        limit = self.parse_int_clause("LIMIT")
        offset = self.parse_int_clause("OFFSET")
        if self.peek().kind != "EOF":
            raise self.error("unexpected token")
        return Query(distinct, items, table, join, where, group, having, order, limit, offset)

    def parse_select_list(self) -> tuple:
        items = [self.parse_select_item()]
        while self.accept_op(","):
            items.append(self.parse_select_item())
        return tuple(items)

    def parse_select_item(self) -> SelectItem | Star:
        if self.accept_op("*"):
            return Star(None)
        if self.peek().kind == "IDENT" and self.is_op(".", 1) and self.is_op("*", 2):
            table = str(self.advance().value)
            self.advance()
            self.advance()
            return Star(table)
        start = self.peek().offset
        expr = self.parse_expr()
        text = " ".join(self.src[start:self.last_end].split())
        alias = self.expect_ident() if self.accept_kw("AS") else None
        return SelectItem(expr, alias, text)

    def parse_join(self) -> Join | None:
        if self.accept_kw("LEFT"):
            kind = "LEFT"
        elif self.accept_kw("INNER"):
            kind = "INNER"
        elif self.is_kw("JOIN"):
            kind = "INNER"
        else:
            return None
        self.expect_kw("JOIN")
        table = self.expect_ident()
        self.expect_kw("ON")
        return Join(kind, table, self.parse_expr())

    def parse_expr_list(self) -> tuple:
        exprs = [self.parse_expr()]
        while self.accept_op(","):
            exprs.append(self.parse_expr())
        return tuple(exprs)

    def parse_order_list(self) -> tuple:
        items = []
        while True:
            expr = self.parse_expr()
            desc = self.accept_kw("DESC")
            if not desc:
                self.accept_kw("ASC")
            items.append(OrderItem(expr, desc))
            if not self.accept_op(","):
                return tuple(items)

    def parse_int_clause(self, word: str) -> int | None:
        if not self.accept_kw(word):
            return None
        tok = self.peek()
        if tok.kind != "INT":
            raise self.error(f"{word} expects an integer")
        self.advance()
        return int(tok.value)  # type: ignore[call-overload]

    # expressions
    def parse_expr(self) -> Expr:
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = Binary("or", left, self.parse_and())
        return left

    def parse_and(self) -> Expr:
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = Binary("and", left, self.parse_not())
        return left

    def parse_not(self) -> Expr:
        if self.accept_kw("NOT"):
            return Unary("not", self.parse_not())
        return self.parse_predicate()

    def parse_predicate(self) -> Expr:
        left = self.parse_additive()
        tok = self.peek()
        if tok.kind == "OP" and tok.value in CMP_OPS:
            self.advance()
            return Binary(str(tok.value), left, self.parse_additive())
        if self.accept_kw("IS"):
            negated = self.accept_kw("NOT")
            self.expect_kw("NULL")
            return IsNull(left, negated)
        return left

    def parse_additive(self) -> Expr:
        left = self.parse_multiplicative()
        while self.is_op("+") or self.is_op("-"):
            op = str(self.advance().value)
            left = Binary(op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self) -> Expr:
        left = self.parse_unary()
        while self.is_op("*") or self.is_op("/") or self.is_op("%"):
            op = str(self.advance().value)
            left = Binary(op, left, self.parse_unary())
        return left

    def parse_unary(self) -> Expr:
        if self.accept_op("-"):
            return Unary("-", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        tok = self.peek()
        if tok.kind in ("INT", "FLOAT", "TEXT"):
            self.advance()
            return Lit(tok.value, tok.kind)
        if tok.kind == "KW" and tok.value in ("TRUE", "FALSE"):
            self.advance()
            return Lit(tok.value == "TRUE", "BOOL")
        if tok.kind == "KW" and tok.value == "NULL":
            self.advance()
            return Lit(None, "NULL")
        if tok.kind == "IDENT":
            return self.parse_name()
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        raise self.error("expected an expression")

    def parse_name(self) -> Expr:
        name = str(self.advance().value)
        if self.is_op("("):
            return self.parse_call(name)
        if self.accept_op("."):
            return Col(name, self.expect_ident())
        return Col(None, name)

    def parse_call(self, name: str) -> Call:
        lname = name.lower()
        is_agg = lname in AGGREGATE_NAMES
        if is_agg and self.agg_depth > 0:
            raise self.error("aggregates may not be nested")
        self.expect_op("(")
        if self.is_op("*"):
            if lname != "count":
                raise self.error("'*' is only allowed in count(*)")
            self.advance()
            self.expect_op(")")
            return Call("count", (), True)
        if is_agg:
            self.agg_depth += 1
        args = []
        if not self.is_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")
        if is_agg:
            self.agg_depth -= 1
        return Call(lname, tuple(args), False)

"""Aggregate functions: count, sum, avg, min, max with SQL NULL rules."""

from __future__ import annotations

from .errors import TypeMismatchError
from .value import compare_lt, is_numeric, type_of

AGGREGATE_NAMES = frozenset({"count", "sum", "avg", "min", "max"})


def is_aggregate(name: str) -> bool:
    return name.lower() in AGGREGATE_NAMES


def compute(name: str, values: list[object]) -> object:
    """Aggregate a list of already-evaluated inputs; NULLs are skipped except by count(*)."""
    if name == "count":
        return sum(1 for v in values if v is not None)
    present = [v for v in values if v is not None]
    if name == "sum":
        return _sum(present)
    if name == "avg":
        return _avg(present)
    return _extreme(name, present)


def _numbers(present: list[object], name: str) -> None:
    for v in present:
        if not is_numeric(v):
            raise TypeMismatchError(f"{name}() requires numeric input, got {type_of(v)}")


def _sum(present: list[object]) -> object:
    if not present:
        return None
    _numbers(present, "sum")
    total = sum(present)  # type: ignore[arg-type]
    if all(type_of(v) == "INT" for v in present):
        return total
    return float(total)


def _avg(present: list[object]) -> object:
    if not present:
        return None
    _numbers(present, "avg")
    return float(sum(present)) / len(present)  # type: ignore[arg-type]


def _extreme(name: str, present: list[object]) -> object:
    if not present:
        return None
    best = present[0]
    for v in present[1:]:
        if name == "min" and compare_lt(v, best):
            best = v
        elif name == "max" and compare_lt(best, v):
            best = v
    return best

"""Expression evaluation over a row environment, with scalar functions."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Callable, Iterator

from .aggregate import AGGREGATE_NAMES
from .errors import (
    AggregateError,
    AmbiguousColumnError,
    ArityError,
    GroupingError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownFunctionError,
    UnknownTableError,
)
from .parser import Binary, Call, Col, Expr, IsNull, Lit, Unary
from .value import and_, arith, as_logical, compare, is_numeric, negate, not_, or_, type_of

CMP_OPS = frozenset({"=", "<>", "<", "<=", ">", ">="})


def _label(qualifier: str | None, name: str) -> str:
    return f"{qualifier}.{name}" if qualifier else name


@dataclass(frozen=True)
class Scope:
    """Ordered (table, column) pairs describing the layout of a working row."""

    entries: tuple[tuple[str, str], ...]

    def resolve(self, qualifier: str | None, name: str) -> int:
        if qualifier is not None:
            if qualifier not in {t for t, _ in self.entries}:
                raise UnknownTableError(f"unknown table {qualifier!r}")
            hits = [i for i, e in enumerate(self.entries) if e == (qualifier, name)]
        else:
            hits = [i for i, (_, c) in enumerate(self.entries) if c == name]
        if not hits:
            raise UnknownColumnError(f"unknown column {_label(qualifier, name)!r}")
        if len(hits) > 1:
            raise AmbiguousColumnError(f"ambiguous column {name!r}")
        return hits[0]


@dataclass(frozen=True)
class Env:
    """Evaluation context.

    keys is None outside grouping. In a grouped context it maps grouping
    expressions and aggregate calls to their values for the current group.
    aliases holds SELECT output values; only ORDER BY sees them.
    members holds the rows of the group, used when computing aggregates.
    """

    row: list
    scope: Scope | None
    keys: dict | None = None
    aliases: dict = field(default_factory=dict)
    members: tuple = ()


def evaluate(node: Expr, env: Env) -> object:
    if isinstance(node, Col) and node.qualifier is None and node.name in env.aliases:
        return env.aliases[node.name]
    if env.keys is not None and node in env.keys:
        return env.keys[node]
    if isinstance(node, Lit):
        return node.value
    if isinstance(node, Col):
        return _column(node, env)
    if isinstance(node, Unary):
        return _unary(node, env)
    if isinstance(node, Binary):
        return _binary(node, env)
    if isinstance(node, IsNull):
        result = evaluate(node.operand, env) is None
        return not result if node.negated else result
    return _call(node, env)


def _column(node: Col, env: Env) -> object:
    label = _label(node.qualifier, node.name)
    if env.keys is not None:
        raise GroupingError(f"column {label!r} must appear in GROUP BY or inside an aggregate")
    if env.scope is None:
        raise UnknownColumnError(f"column {label!r} is not available after DISTINCT")
    return env.row[env.scope.resolve(node.qualifier, node.name)]


def _unary(node: Unary, env: Env) -> object:
    value = evaluate(node.operand, env)
    if node.op == "not":
        return not_(as_logical(value))
    return negate(value)


def _binary(node: Binary, env: Env) -> object:
    if node.op in ("and", "or"):
        left = as_logical(evaluate(node.left, env))
        right = as_logical(evaluate(node.right, env))
        return and_(left, right) if node.op == "and" else or_(left, right)
    left_value = evaluate(node.left, env)
    right_value = evaluate(node.right, env)
    if node.op in CMP_OPS:
        return compare(node.op, left_value, right_value)
    return arith(node.op, left_value, right_value)


def _call(node: Call, env: Env) -> object:
    if node.name in AGGREGATE_NAMES:
        raise AggregateError(f"aggregate {node.name}() is not allowed here")
    args = [evaluate(arg, env) for arg in node.args]
    return SCALARS[node.name][2](args)


def children(node: Expr) -> tuple:
    if isinstance(node, Unary):
        return (node.operand,)
    if isinstance(node, Binary):
        return (node.left, node.right)
    if isinstance(node, IsNull):
        return (node.operand,)
    if isinstance(node, Call):
        return tuple(node.args)
    return ()


def iter_nodes(node: Expr) -> Iterator[Expr]:
    """Yield node and all of its descendants, depth first."""
    yield node
    for child in children(node):
        yield from iter_nodes(child)


def _expected(lo: int, hi: int | None) -> str:
    if hi is None:
        return f"at least {lo}"
    if lo == hi:
        return str(lo)
    return f"{lo} to {hi}"


def check_call(node: Call) -> None:
    """Static check of a call's name and argument count."""
    n = len(node.args)
    if node.name in AGGREGATE_NAMES:
        if not node.star and n != 1:
            raise ArityError(f"{node.name}() expects 1 argument(s), got {n}")
        return
    if node.name not in SCALARS:
        raise UnknownFunctionError(f"unknown function {node.name}()")
    lo, hi, _ = SCALARS[node.name]
    if n < lo or (hi is not None and n > hi):
        raise ArityError(f"{node.name}() expects {_expected(lo, hi)} argument(s), got {n}")


def _check_text(name: str, values: list[object]) -> None:
    for v in values:
        if v is not None and not isinstance(v, str):
            raise TypeMismatchError(f"{name}() requires TEXT arguments, got {type_of(v)}")


def _concat(args: list[object]) -> object:
    _check_text("concat", args)
    if any(a is None for a in args):
        return None
    return "".join(args)  # type: ignore[arg-type]


def _text_fn(name: str, fn: Callable[[str], object]) -> Callable[[list[object]], object]:
    def run(args: list[object]) -> object:
        _check_text(name, args)
        return None if args[0] is None else fn(args[0])  # type: ignore[arg-type]
    return run


def _abs(args: list[object]) -> object:
    value = args[0]
    if value is not None and not is_numeric(value):
        raise TypeMismatchError(f"abs() requires a numeric argument, got {type_of(value)}")
    return None if value is None else abs(value)  # type: ignore[arg-type]


def _coalesce(args: list[object]) -> object:
    return next((a for a in args if a is not None), None)


SCALARS: dict[str, tuple[int, int | None, Callable[[list[object]], object]]] = {
    "concat": (2, None, _concat),
    "upper": (1, 1, _text_fn("upper", str.upper)),
    "lower": (1, 1, _text_fn("lower", str.lower)),
    "length": (1, 1, _text_fn("length", len)),
    "abs": (1, 1, _abs),
    "coalesce": (1, None, _coalesce),
}

"""Planner: turns a Query into an ordered Plan of named stages."""

from __future__ import annotations

from dataclasses import dataclass
from typing import ClassVar, Iterator

from .aggregate import AGGREGATE_NAMES
from .errors import AggregateError, GroupingError
from .expr import check_call, children, iter_nodes
from .parser import Call, Col, Expr, Join, OrderItem, Query, SelectItem, Star


@dataclass(frozen=True)
class ScanStage:
    name: ClassVar[str] = "scan"
    table: str
    join: Join | None


@dataclass(frozen=True)
class FilterStage:
    name: ClassVar[str] = "filter"
    predicate: Expr


@dataclass(frozen=True)
class GroupStage:
    name: ClassVar[str] = "group"
    keys: tuple


@dataclass(frozen=True)
class AggregateStage:
    name: ClassVar[str] = "aggregate"
    calls: tuple


@dataclass(frozen=True)
class HavingStage:
    name: ClassVar[str] = "having"
    predicate: Expr


@dataclass(frozen=True)
class ProjectStage:
    name: ClassVar[str] = "project"
    items: tuple


@dataclass(frozen=True)
class DistinctStage:
    name: ClassVar[str] = "distinct"


@dataclass(frozen=True)
class SortStage:
    name: ClassVar[str] = "sort"
    keys: tuple[OrderItem, ...]


@dataclass(frozen=True)
class SliceStage:
    name: ClassVar[str] = "slice"
    offset: int | None
    limit: int | None


class Plan:
    """An inspectable, ordered sequence of stages. Building it does not execute anything."""

    def __init__(self, stages: tuple) -> None:
        self._stages = tuple(stages)

    def __iter__(self) -> Iterator[object]:
        return iter(self._stages)

    def __len__(self) -> int:
        return len(self._stages)

    def __getitem__(self, index: int) -> object:
        return self._stages[index]

    @property
    def names(self) -> list[str]:
        return [stage.name for stage in self._stages]  # type: ignore[attr-defined]


def plan(query: Query) -> Plan:
    """Validate the query and build its stage pipeline."""
    _validate(query)
    aggs = _collect_aggregates(query)
    grouped = bool(query.group) or bool(aggs)
    stages: list[object] = [ScanStage(query.table, query.join)]
    if query.where is not None:
        stages.append(FilterStage(query.where))
    if grouped:
        _check_grouping(query)
        stages.append(GroupStage(query.group))
        stages.append(AggregateStage(aggs))
    if query.having is not None:
        stages.append(HavingStage(query.having))
    stages.append(ProjectStage(query.items))
    if query.distinct:
        stages.append(DistinctStage())
    if query.order:
        stages.append(SortStage(query.order))
    if query.limit is not None or query.offset is not None:
        stages.append(SliceStage(query.offset, query.limit))
    return Plan(tuple(stages))


def _all_exprs(query: Query) -> list[Expr]:
    exprs: list[Expr] = [item.expr for item in query.items if isinstance(item, SelectItem)]
    exprs += list(query.group)
    exprs += [o.expr for o in query.order]
    for extra in (query.where, query.having, query.join.on if query.join else None):
        if extra is not None:
            exprs.append(extra)
    return exprs


def _validate(query: Query) -> None:
    for expr in _all_exprs(query):
        for node in iter_nodes(expr):
            if isinstance(node, Call):
                check_call(node)
    for label, expr in _aggregate_free_exprs(query):
        if any(isinstance(n, Call) and n.name in AGGREGATE_NAMES for n in iter_nodes(expr)):
            raise AggregateError(f"aggregates are not allowed in {label}")


def _aggregate_free_exprs(query: Query) -> list[tuple[str, Expr]]:
    pairs = [("WHERE", query.where), ("GROUP BY", None), ("JOIN ON", query.join.on if query.join else None)]
    result = [(label, e) for label, e in pairs if e is not None]
    result += [("GROUP BY", k) for k in query.group]
    return result


def _collect_aggregates(query: Query) -> tuple:
    """Distinct aggregate calls from SELECT, HAVING and ORDER BY, in first-seen order."""
    roots: list[Expr] = [item.expr for item in query.items if isinstance(item, SelectItem)]
    roots += [query.having] if query.having is not None else []
    roots += [o.expr for o in query.order]
    seen: dict[Call, None] = {}
    for root in roots:
        for node in iter_nodes(root):
            if isinstance(node, Call) and node.name in AGGREGATE_NAMES:
                seen.setdefault(node, None)
    return tuple(seen)


def _check_grouping(query: Query) -> None:
    aliases = _output_names(query)
    for item in query.items:
        if isinstance(item, Star):
            raise GroupingError("'*' cannot be used with GROUP BY or aggregates")
        _check_group_expr(item.expr, query.group, frozenset())
    if query.having is not None:
        _check_group_expr(query.having, query.group, frozenset())
    for order in query.order:
        _check_group_expr(order.expr, query.group, aliases)


def _output_names(query: Query) -> frozenset[str]:
    names = set()
    for item in query.items:
        if isinstance(item, SelectItem):
            if item.alias is not None:
                names.add(item.alias)
            elif isinstance(item.expr, Col):
                names.add(item.expr.name)
            else:
                names.add(item.text)
    return frozenset(names)


def _check_group_expr(node: Expr, keys: tuple, aliases: frozenset[str]) -> None:
    """Every column must be a grouping key, an alias (ORDER BY only) or inside an aggregate."""
    if node in keys:
        return
    if isinstance(node, Call) and node.name in AGGREGATE_NAMES:
        return
    if isinstance(node, Col):
        if node.qualifier is None and node.name in aliases:
            return
        raise GroupingError(f"column {node.name!r} must appear in GROUP BY or inside an aggregate")
    for child in children(node):
        _check_group_expr(child, keys, aliases)

args.new_str:
def _aggregate_free_exprs(query: Query) -> list[tuple[str, Expr]]:
    """Clauses in which aggregates are forbidden, with their names for messages."""
    result: list[tuple[str, Expr]] = []
    if query.where is not None:
        result.append(("WHERE", query.where))
    if query.join is not None:
        result.append(("JOIN ON", query.join.on))
    result += [("GROUP BY", key) for key in query.group]
    return result

